package net.officefloor.hq.app.person;

/** The person form: the request body to add or edit a person. An edit carries the {@code version}
 *  of the person its form loaded (null when adding). */
public record PersonRequest(String name, String grade, Long version) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person) {
        person.setName(request.name());
        person.setGrade(request.grade());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class CreatePerson {
    public void create(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository, Out<Person> person) {
        person.set(repository.create(sheetId, request.name(), request.grade()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the edited person once every rule has passed and it is saved. */
public class AuditPersonEdited {
    public void audit(@Val Person person, @RequestParam(value = "user", required = false) String user, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.getGrade());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the added person once every rule has passed and it is stored. */
public class AuditPersonAdded {
    public void audit(@Val Person person, @RequestParam(value = "user", required = false) String user, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.getGrade());
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person as the screen shows it, with the version an edit form sends back, and their statements:
 *  how many were taken, the last one's due-total (null: none taken, or n/a) and date (null: none taken),
 *  whether they are retired and from when (null: not retired), and whether they are on hold, and their patrons' names, sorted. */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<String> patrons) {
    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() == null ? null : person.getStatedTotal().toPlainString(),
                person.getStatementDate() == null ? null : person.getStatementDate().toString(),
                person.getRetiredFrom() != null,
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                person.isHeld(), List.copyOf(person.getPatrons()));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, PersonRepository repository,
            ObjectResponse<List<PersonResponse>> response) {
        response.send(repository.findBySheet(sheetId).stream().map(PersonResponse::from).toList());
    }
}
