package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * Each sheet's "today". It starts as the real date and is changed from the screen. Every decision
 * that depends on the date, and every default date, uses {@link #today(String)} — never the real
 * clock.
 */
@Service
public class SheetClock {

    private final JdbcTemplate jdbc;

    public SheetClock(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today: the stored date, or the real date when none has been set. */
    public LocalDate today(String sheetId) {
        List<Date> stored = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
        Date today = stored.isEmpty() ? null : stored.get(0);
        return today == null ? LocalDate.now() : today.toLocalDate();
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, Date.valueOf(today));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * The person the quick-add names (ignoring case). A name not on the sheet adds the person with grade
 * A, recorded as the person form records it — PERSON_ADDED then its ROLLUP lines — ahead of the claim.
 * Runs once every rule has passed, so a refused quick-add adds no one.
 */
public class ResolveQuickPerson {
    public void resolve(@PathVariable("sheetId") String sheetId, @Val QuickAdd quick,
            @RequestParam(value = "user", required = false) String user, PersonRepository repository,
            Rollup rollup, Audit audit, Out<Person> personOut) {
        Person person = repository.findByName(sheetId, quick.name());
        if (person == null) {
            Rollup.Snapshot before = rollup.take(sheetId);
            person = repository.create(sheetId, quick.name(), "A");
            audit.record("PERSON_ADDED sheet=" + sheetId + " by=" + user
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.changes(sheetId, user, before, rollup.take(sheetId)).forEach(audit::record);
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim the sheet's next number, which it keeps when voided. Settling fixes the claim's
 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
 *  The user who opened a claim may not settle it (four eyes).
 *  Publishes the number the audit line carries. */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, Out<ClaimNumber> numberOut,
            @RequestParam(value = "user", required = false) String user)
            throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
        }
        // The late charge is worked out while the claim is still OPEN, so settling freezes it in.
        BigDecimal settledDue = action != ClaimAction.SETTLE ? null : latePct.of(claim.getSheetId())
                .addTo(claim, claim.isStated() ? claim.getStatedDue() : dueNow(claim, people, rates, floor));
        claim.setStatus(action.to());
        switch (action) {
            case OPEN -> {
                claim.setNumber(repository.nextNumber(claim.getSheetId()));
                claim.setOpenedBy(user);
            }
            case SETTLE -> claim.setSettledDue(settledDue);
            default -> { }
        }
        numberOut.set(new ClaimNumber(claim.getNumber()));
    }

    /** amount × pct / 100, rounded half to even to two decimals and at least the floor; null when no rate is in force on the claim's date. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        return Floor.raise(Rate.inForce(rates.findBySheet(claim.getSheetId()), person.getGrade(), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null), floor.of(claim.getSheetId()));
    }
}
