        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), dated.grade(),
                dated.from() == null ? null : Date.valueOf(dated.from()));
