for (Person person : people.findBySheet(sheetId)) {
    BigDecimal claimed = zero();
    BigDecimal due = zero();
    boolean fixed = false;
    for (Claim claim : sheetClaims) {
        if (claim.getPersonId() != person.getId()) continue;
        if (!person.counts(claim.getStatus())) continue;
        claimed = claimed.add(claim.getAmount());
        if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
        BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least));
        if (figure != null) due = due.add(figure);
    }
    boolean na = Rate.inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !fixed;
    claimedTotal = claimedTotal.add(claimed);
    if (!na) dueTotal = dueTotal.add(due);
    boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
    if (counts && !person.counts(claim.getStatus())) {
        continue;           // a held person's OPEN claim: in no total, and left as it is
    } else if (!counts) {
        claim.setStated(false);
        claim.setStatedDue(null);
    } else {
        BigDecimal figure = figure(claim, person, rates, least);
        if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
        BigDecimal due = late.addTo(claim, figure);
        if (due != null) sum = sum.add(due);
        claim.setStated(true);
        claim.setStatedDue(figure);
        counted++;
    }
    claims.save(claim);
}
BigDecimal dueTotal = Rate.inForce(rates, person.gradeOn(today), today).isEmpty() && !fixed ? null : sum;
person.setStatementCount(person.getStatementCount() + 1);

